# 3. BỘ DỰNG GIAO DIỆN WEB THUẦN PYTHON (PURE PYTHON COMPONENT ENGINE)
# ==============================================================================
_LT = chr(60)
_GT = chr(62)
_VOID_ELEMENTS = frozenset([
    "area", "base", "br", "col", "embed", "hr", "img",
    "input", "link", "meta", "param", "source", "track", "wbr"
])


class PyElement:
    """Lớp biểu diễn phần tử giao diện Web bằng đối tượng Python thuần túy (Pure Python Component Tree)."""

    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None, *children):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        for ch in children:
            if ch is None or ch is False:
                continue
            if isinstance(ch, (list, tuple)):
                self.children.extend(x for x in ch if x is not None and x is not False)
            else:
                self.children.append(ch)

    def render(self):
        attr_parts = []
        for k, v in self.attrs.items():
            if v is None or v is False:
                continue
            if v is True or v == "":
                attr_parts.append(f' {k}=""')
            else:
                escaped_v = str(v).replace('"', "&quot;")
                attr_parts.append(f' {k}="{escaped_v}"')
        attr_str = "".join(attr_parts)

        if self.tag in _VOID_ELEMENTS:
            return f"{_LT}{self.tag}{attr_str}{_GT}"

        inner = "".join(
            ch.render() if isinstance(ch, PyElement) else str(ch)
            for ch in self.children
        )
        return f"{_LT}{self.tag}{attr_str}{_GT}{inner}{_LT}/{self.tag}{_GT}"


def el(tag, attrs=None, *children):
    return PyElement(tag, attrs, *children)


