def compile_stylesheet():
    blocks = []
    for selector, props in STYLE_RULES:
        prop_str = "; ".join(f"{k}: {v}" for k, v in props.items())
        blocks.append(f"{selector} {{ {prop_str}; }}")
    blocks.extend(KEYFRAME_RULES)
    return "\n".join(blocks)


