# 5. WEB SERVER PYTHON ĐA NỀN TẢNG (ASGI UVICORN + WSGI GUNICORN + HTTP SERVER)
# ==============================================================================
STATUS_TEXT = {
    200: "200 OK",
    204: "204 No Content",
    404: "404 Not Found",
    500: "500 Internal Server Error",
}


def _route_http_request(method, path, raw_body_bytes=b""):
    method = (method or "GET").upper()
    parsed_path = urlparse(path or "/").path or "/"

    cors_headers = [
        ("Access-Control-Allow-Origin", "*"),
        ("Access-Control-Allow-Methods", "GET, POST, OPTIONS, HEAD"),
        ("Access-Control-Allow-Headers", "Content-Type, Accept"),
    ]

    if method == "OPTIONS":
        return 204, cors_headers, b""

    if parsed_path in ("/", "/app"):
        body = get_rendered_web_app_bytes()
        headers = [
            ("Content-Type", "text/\x68\x74\x6d\x6c; charset=utf-8"),
            ("Content-Length", str(len(body))),
            ("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0"),
            ("Pragma", "no-cache"),
            ("Expires", "0"),
        ] + cors_headers
        return 200, headers, (b"" if method == "HEAD" else body)

    if parsed_path in ("/api/health", "/healthz"):
        body = json.dumps({
            "status": "ok",
            "engine": "Pure Python Web App (PyElement)",
            "cameras": len(CAMERAS),
            "rules": len(expert_system.rules),
            "flagship_showcase": len(FLAGSHIP_5_BRANDS),
        }, ensure_ascii=False).encode("utf-8")
        headers = [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ] + cors_headers
        return 200, headers, (b"" if method == "HEAD" else body)

    if parsed_path == "/api/kb":
        body = json.dumps({
            "facts_meta": expert_system.facts_meta,
            "cameras": list(expert_system.cameras.values()),
            "rules": expert_system.rules,
            "flagship_5_brands": FLAGSHIP_5_BRANDS,
        }, ensure_ascii=False).encode("utf-8")
        headers = [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ] + cors_headers
        return 200, headers, (b"" if method == "HEAD" else body)

    if parsed_path == "/api/consult":
        if method == "POST" and raw_body_bytes:
            try:
                payload = json.loads(raw_body_bytes.decode("utf-8"))
            except Exception:
                payload = {}
            facts = payload.get("facts", [])
        else:
            facts = []
        result = expert_system.forward_chaining(facts)
        body = json.dumps(result, ensure_ascii=False).encode("utf-8")
        headers = [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ] + cors_headers
        return 200, headers, (b"" if method == "HEAD" else body)

    if parsed_path == "/api/filter" and method == "POST":
        try:
            payload = json.loads(raw_body_bytes.decode("utf-8")) if raw_body_bytes else {}
        except Exception:
            payload = {}
        cameras_filtered = expert_system.filter_cameras(
            selected_facts=payload.get("facts", []),
            search_query=payload.get("search", ""),
            sort_mode=payload.get("sort", "popular"),
            in_stock_only=bool(payload.get("in_stock_only", False)),
        )
        body = json.dumps({"count": len(cameras_filtered), "cameras": cameras_filtered}, ensure_ascii=False).encode("utf-8")
        headers = [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ] + cors_headers
        return 200, headers, body

    if parsed_path == "/api/add-rule" and method == "POST":
        global _CACHED_WEB_APP_BYTES
        try:
            payload = json.loads(raw_body_bytes.decode("utf-8")) if raw_body_bytes else {}
        except Exception:
            payload = {}
        conditions = payload.get("conditions", [])
        conclusion = payload.get("conclusion", "K1")
        description = payload.get("description", "")
        new_rule = expert_system.add_rule(conditions, conclusion, description)
        _CACHED_WEB_APP_BYTES = None
        body = json.dumps(
            {"status": "ok", "rule": new_rule, "total_rules": len(expert_system.rules)},
            ensure_ascii=False
        ).encode("utf-8")
        headers = [
            ("Content-Type", "application/json; charset=utf-8"),
            ("Content-Length", str(len(body))),
        ] + cors_headers
        return 200, headers, body

    body = json.dumps({"error": "Endpoint not found"}, ensure_ascii=False).encode("utf-8")
    headers = [
        ("Content-Type", "application/json; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ] + cors_headers
    return 404, headers, (b"" if method == "HEAD" else body)


class HybridWSGIASGIApp:
    def __call__(self, *args):
        if len(args) == 2 and callable(args[1]):
            environ, start_response = args
            return self._handle_wsgi(environ, start_response)
        if len(args) == 3:
            scope, receive, send = args
            return self._handle_asgi(scope, receive, send)
        if len(args) == 1 and isinstance(args[0], dict):
            scope = args[0]

            async def asgi2_instance(receive, send):
                await self._handle_asgi(scope, receive, send)

            return asgi2_instance
        raise TypeError(f"Unsupported application call signature with {len(args)} argument(s).")

    def _handle_wsgi(self, environ, start_response):
        method = environ.get("REQUEST_METHOD", "GET").upper()
        path = environ.get("PATH_INFO", "/")
        try:
            length = int(environ.get("CONTENT_LENGTH") or 0)
        except ValueError:
            length = 0
        raw_body = environ["wsgi.input"].read(length) if length > 0 and "wsgi.input" in environ else b""
        status_code, headers, body = _route_http_request(method, path, raw_body)
        start_response(STATUS_TEXT.get(status_code, f"{status_code} OK"), headers)
        return [body]

    async def _handle_asgi(self, scope, receive, send):
        scope_type = scope.get("type")
        if scope_type == "lifespan":
            while True:
                message = await receive()
                if message["type"] == "lifespan.startup":
                    await send({"type": "lifespan.startup.complete"})
                elif message["type"] == "lifespan.shutdown":
                    await send({"type": "lifespan.shutdown.complete"})
                    return
        if scope_type != "http":
            return

        method = scope.get("method", "GET").upper()
        path = scope.get("path", "/")
        body_chunks = []
        while True:
            message = await receive()
            if message["type"] == "http.request":
                chunk = message.get("body", b"")
                if chunk:
                    body_chunks.append(chunk)
                if not message.get("more_body", False):
                    break
            elif message["type"] == "http.disconnect":
                return

        raw_body = b"".join(body_chunks)
        status_code, headers, response_body = _route_http_request(method, path, raw_body)
        asgi_headers = [(k.lower().encode("latin-1"), v.encode("latin-1")) for k, v in headers]
        await send({"type": "http.response.start", "status": status_code, "headers": asgi_headers})
        await send({"type": "http.response.body", "body": b"" if method == "HEAD" else response_body})


app = HybridWSGIASGIApp()
application = app


class ExpertSystemRequestHandler(BaseHTTPRequestHandler):
    def do_OPTIONS(self):
        status_code, headers, _ = _route_http_request("OPTIONS", self.path)
        self.send_response(status_code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()

    def do_HEAD(self):
        status_code, headers, _ = _route_http_request("HEAD", self.path)
        self.send_response(status_code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()

    def do_GET(self):
        status_code, headers, body = _route_http_request("GET", self.path)
        self.send_response(status_code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        content_len = int(self.headers.get("Content-Length", 0))
        raw_body = self.rfile.read(content_len) if content_len > 0 else b"{}"
        status_code, headers, body = _route_http_request("POST", self.path, raw_body)
        self.send_response(status_code)
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *args):
        print(f"[MingDShop Python Web] {self.address_string()} - {fmt % args}")


