def _load_embedded_visual_assets():
    raw_bytes = zlib.decompress(base64.b64decode(_PACKED_VISUAL_ASSETS))
    payload = json.loads(raw_bytes.decode("utf-8"))
    cam_imgs = payload.get("camera_images", {})
    banners_data = payload.get("banners", {})
    hd_cams = banners_data.get("hd_cams", {})
    for cam_obj in CAMERAS:
        cid = cam_obj["id"]
        cam_obj["image"] = cam_imgs.get(cid) or hd_cams.get(cid, "")
        if cid in expert_system.cameras:
            expert_system.cameras[cid]["image"] = cam_obj["image"]
    return banners_data


BANNERS = _load_embedded_visual_assets()

def _release_stale_port(port):
    """Tự động giải phóng cổng nếu có tiến trình Server cũ đang chạy ngầm trong VS Code."""
    import subprocess
    my_pid = str(os.getpid())
    if os.name == "nt":
        try:
            out = subprocess.check_output(f"netstat -ano | findstr :{port}", shell=True, text=True, stderr=subprocess.DEVNULL)
            for line in out.splitlines():
                parts = line.strip().split()
                if len(parts) >= 5 and "LISTENING" in line.upper():
                    pid = parts[-1]
                    if pid.isdigit() and pid != "0" and pid != my_pid:
                        subprocess.run(f"taskkill /F /PID {pid}", shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass


