        port = int(os.environ.get("PORT", 8000))
        if not os.environ.get("RENDER"):
            _release_stale_port(port)
        server = ThreadingHTTPServer(("0.0.0.0", port), ExpertSystemRequestHandler)
        url = f"http://localhost:{port}"
